insomnia.test('Envelope do conflito da aula encontrado', () => {
  const id = Number(insomnia.environment.get('product_id'));
  const found = insomnia.response.json().some(message => {
    try { const event = JSON.parse(message.payload); return event.productId === id && event.data.name === 'Nome conflitante'; }
    catch { return false; }
  });
  insomnia.expect(found).to.eql(true);
});

